import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"死代码消除与 ADCE","description":"","frontmatter":{"title":"死代码消除与 ADCE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dce-adce.md","filePath":"cs/dce-adce.md","lastUpdated":1789023840000}'),p={name:"cs/dce-adce.md"};function h(C,a,D,u,A,_){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="死代码消除与-adce" tabindex="-1">死代码消除与 ADCE <a class="header-anchor" href="#死代码消除与-adce" aria-label="Permalink to &quot;死代码消除与 ADCE&quot;">​</a></h1><div class="epigraph"><p>若赋值的结果从不被观察，且运算无副作用，则可删。激进 DCE 从必要指令反推，未碰到的一律死。</p><footer>—— 据 Cytron 等 SSA；Muchnick, Advanced Compiler Design；LLVM ADCE 实践；龙书死代码整理</footer></div><p>上一课<a href="/cs/cse-gvn">CSE/GVN</a>留下拷贝与可删的重复运算。缺口是<strong>死代码</strong>：无用赋值、不可达块、SCCP 钉死的枝。普通 DCE 看 def-use；ADCE（aggressive）从「必要」种子（store、return、volatile、有副作用的调用）沿反向依赖与控制依赖扩张。本课钉必要集，不写完整 CDG 算法细节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SSA 上：若名无 use 且右部纯，删赋值。φ 的 use 没了可再删，迭代。控制流：条件若只服务死赋值，分支可折成跳转。缺口是<strong>观察点</strong>，不是值编号。</p><p>副作用：<code>free</code>、IO、<code>volatile</code> 是种子。语言若允许省略无观察的 store，规则随内存模型——后课 UB。</p><h3 id="死不是「程序员没读变量」" tabindex="-1">死不是「程序员没读变量」 <a class="header-anchor" href="#死不是「程序员没读变量」" aria-label="Permalink to &quot;死不是「程序员没读变量」&quot;">​</a></h3><p>逃逸到内存、通过指针读，算观察。无<a href="/cs/alias-analysis">别名分析</a> 时，对 store 必须保守当活。本课标量 SSA 可激进；内存保守。</p><p><span class="marginnote">Muchnick 有 DCE 章。Cytron 指出 SSA 使死代码显然。Ferrante 等控制依赖。LLVM 的 ADCE/BDCE 是工程名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标记：从种子工作表反向：指令的操作数变必要；控制依赖的分支变必要。未标记删除。不可达块：CFG 从入口 DFS。</p>',11)),(e(),n(E,null,{default:r(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E5%89%AF%E4%BD%9C%E7%94%A8%20%2F%20%E8%BF%94%E5%9B%9E%22%5D%20--%3E%20REV%5B%22%E5%8F%8D%E5%90%91%E4%BE%9D%E8%B5%96%22%5D%0A%20%20REV%20--%3E%20LIVE%5B%22%E5%BF%85%E8%A6%81%E6%8C%87%E4%BB%A4%22%5D%0A%20%20LIVE%20--%3E%20DEL%5B%22%E5%88%A0%E9%99%A4%E5%85%B6%E4%BD%99%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 SCCP：不可执行边先删，减少种子。二者顺序可迭代至不动点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>调试信息：删指令要决定是否保留位置——DWARF 后课。不要把 ADCE 当混淆器的「删所有」；种子错则改变语义。</p><p>无穷循环无副作用：C++ 曾允许删除，现更谨慎；这是语言律师问题，分析须按所选标准。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写部分死（某些路径死）。后课默认：无观察的纯赋值可删。下一课 LICM：活但循环不变的计算往外搬，不是删。</p><p>也不把 DCE 当链接期 GC 节。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DCE 删无 use 的纯赋值；ADCE 从观察点反推必要集。</li><li>内存与副作用必须当种子或保守。</li><li>与 SCCP 交替，清死枝。</li><li>出处：Cytron et al.；Muchnick；对照龙书；Ferrante 控制依赖。</li></ul>',9))])}const S=s(p,[["render",h]]);export{f as __pageData,S as default};
